<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('commercial_manager');$user=current_user();$flashes=render_flashes();$currentPage='saved_search_view';$pageTitle='Saved Search Details';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);$id=(int)($_GET['id']??0);
$s=$conn->prepare("SELECT * FROM commercial_saved_searches WHERE id=? AND commercial_manager_id=? LIMIT 1");$s->bind_param('ii',$id,$managerId);$s->execute();$search=$s->get_result()->fetch_assoc();$s->close();if(!$search){http_response_code(403);exit('Saved search not found.');}
$criteria=cm_json($search['criteria_json']);$rows=[];$s=$conn->prepare("SELECT * FROM commercial_saved_search_breakdowns WHERE saved_search_id=? ORDER BY dimension_name,candidate_count DESC");$s->bind_param('i',$id);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();$threshold=cm_threshold($conn);
require __DIR__.'/_layout_start.php';?>
<div class="cm-page-header"><div><span>Saved Search Snapshot</span><h2><?= e($search['search_name']) ?></h2><p><?= number_format((int)$search['result_count']) ?> results · Taxonomy <?= e($search['taxonomy_version']) ?> · <?= e(cm_currency($search['data_snapshot_at'])) ?></p></div><a class="cm-btn cm-btn--primary" href="<?= url('commercial_manager/generate_pack.php?saved_search_id='.$id) ?>"><i class="fas fa-file-circle-plus"></i> Generate Pack</a></div>
<div class="cm-grid"><section class="cm-card"><div class="cm-card__header"><h3>Search Criteria</h3></div><div class="cm-detail-grid"><?php foreach($criteria as $k=>$v):?><div><span><?= e(cm_label((string)$k)) ?></span><strong><?= e(is_array($v)?implode(', ',$v):(string)$v) ?></strong></div><?php endforeach;?></div></section><section class="cm-card"><div class="cm-card__header"><h3>Snapshot Integrity</h3></div><div class="cm-principles"><div><i class="fas fa-users"></i><strong><?= number_format((int)$search['result_count']) ?></strong><span>reconciled candidates</span></div><div><i class="fas fa-clock"></i><strong><?= e(cm_datetime($search['data_snapshot_at'])) ?></strong><span>data snapshot</span></div></div></section></div>
<div class="cm-card"><div class="cm-card__header"><div><h3>Anonymised Breakdown Preview</h3><p>Groups below <?= $threshold ?> are suppressed.</p></div></div><div class="cm-table-wrap"><table><thead><tr><th>Dimension</th><th>Group</th><th>Count</th><th>Verified</th><th>Currency</th></tr></thead><tbody><?php foreach($rows as $x):$c=(int)$x['candidate_count'];$sup=$c>0&&$c<$threshold;?><tr><td><?= e(cm_label($x['dimension_name'])) ?></td><td><?= $sup?'Suppressed group':e($x['dimension_value']) ?></td><td><?= $sup?'&lt;'.$threshold:number_format($c) ?></td><td><?= $sup?'Suppressed':number_format((int)$x['verified_count']) ?></td><td><?= e(cm_currency($x['most_recent_verification_at'])) ?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require __DIR__.'/_layout_end.php';?>